"""数据处理 runner 模块。"""

import csv
import json
import os


class HarnessError(Exception):
    """表示处理失败的异常。"""
    pass


def _read_csv(path):
    """读取 CSV 文件，跳过空行，返回记录列表。"""
    records = []
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        for row in reader:
            if any(v is not None for v in row.values()):
                records.append(row)
    return records


def _read_jsonl(path):
    """读取 JSONL 文件，跳过空行，返回记录列表。"""
    records = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            stripped = line.strip()
            if not stripped:
                continue
            records.append(json.loads(stripped))
    return records


def _read_input(path):
    """根据扩展名选择合适的读取器。"""
    ext = os.path.splitext(path)[1].lower()
    if ext == ".csv":
        return _read_csv(path)
    elif ext == ".jsonl":
        return _read_jsonl(path)
    else:
        raise HarnessError(f"不支持的文件类型: {path}")


def run_dag(input_paths, output_path=None):
    """处理输入文件并返回报告字典。

    Args:
        input_paths: 输入文件路径列表。
        output_path: 可选的输出文件路径；若提供则将报告写入该文件。

    Returns:
        包含 processed_count, rejected_count, retry_count, source_files 的字典。

    Raises:
        HarnessError: 处理失败时抛出。
    """
    try:
        processed = 0
        rejected = 0

        all_records = []
        for path in input_paths:
            all_records.extend(_read_input(path))

        for record in all_records:
            record_id = record.get("id")
            if record_id is not None and record_id != "":
                processed += 1
            else:
                rejected += 1

        report = {
            "processed_count": processed,
            "rejected_count": rejected,
            "retry_count": 0,
            "source_files": [os.path.normpath(p) for p in input_paths],
        }

        if output_path is not None:
            os.makedirs(os.path.dirname(output_path) or ".", exist_ok=True)
            with open(output_path, "w", encoding="utf-8") as f:
                json.dump(report, f, indent=2)

        return report

    except Exception as e:
        raise HarnessError(str(e)) from e

